interface UIFactory {
  createButton(): Button;
  createCheckbox(): Checkbox;
}

class LightFactory implements UIFactory { /* returns LightButton, LightCheckbox */ }
class DarkFactory implements UIFactory { /* returns DarkButton, DarkCheckbox */ }

function render(uiFactory: UIFactory) {
  const btn = uiFactory.createButton();
  const cb = uiFactory.createCheckbox();
  btn.render(); cb.render();
}

function createButton(theme: 'light' | 'dark') {
  if (theme === 'light') return new LightButton();
  return new DarkButton();
}

class LightButton { render() {} }
class DarkButton { render() {} }

const btn = createButton(getCurrentTheme());
btn.render();

/* Version A */
interface WidgetFactory { createButton(): Button; createCheckbox(): Checkbox }
function render(factory: WidgetFactory) {
  const btn = factory.createButton();
  const cb = factory.createCheckbox();
  btn.render(); cb.render();
}

/* Version B */
function render(theme: string) {
  const btn = theme === 'light' ? new LightButton() : new DarkButton();
  const cb = theme === 'light' ? new LightCheckbox() : new DarkCheckbox();
  btn.render(); cb.render();
}
